'use strict';

// MODULES //

var bench = require( '@stdlib/bench' );
var discreteUniform = require( '@stdlib/random/array/discrete-uniform' );
var isColumnMajor = require( '@stdlib/ndarray/base/assert/is-column-major-string' );
var Float64Array = require( '@stdlib/array/float64' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var pow = require( '@stdlib/math/base/special/pow' );
var floor = require( '@stdlib/math/base/special/floor' );
var format = require( '@stdlib/string/format' );
var pkg = require( './../package.json' ).name;
var dlabrd = require( './../lib/ndarray.js' );


// VARIABLES //

var LAYOUTS = [
	'row-major',
	'column-major'
];
var opts = {
	'dtype': 'float64'
};


// FUNCTIONS //

/**
* Creates a benchmark function.
*
* @private
* @param {string} order - storage layout
* @param {PositiveInteger} M - number of rows
* @param {PositiveInteger} N - number of columns
* @param {PositiveInteger} NB - number of leading rows and columns to reduce
* @returns {Function} benchmark function
*/
function createBenchmark( order, M, N, NB ) {
	var TAUQ;
	var TAUP;
	var sA1;
	var sA2;
	var sX1;
	var sX2;
	var sY1;
	var sY2;
	var A;
	var D;
	var E;
	var X;
	var Y;

	A = discreteUniform( M * N, 1.0, 10.0, opts );
	D = new Float64Array( NB );
	E = new Float64Array( NB );
	TAUQ = new Float64Array( NB );
	TAUP = new Float64Array( NB );
	X = new Float64Array( M * NB );
	Y = new Float64Array( N * NB );
	if ( isColumnMajor( order ) ) {
		sA1 = 1;
		sA2 = M;
		sX1 = 1;
		sX2 = M;
		sY1 = 1;
		sY2 = N;
	} else { // order === 'row-major'
		sA1 = N;
		sA2 = 1;
		sX1 = NB;
		sX2 = 1;
		sY1 = NB;
		sY2 = 1;
	}
	return benchmark;

	/**
	* Benchmark function.
	*
	* @private
	* @param {Benchmark} b - benchmark instance
	*/
	function benchmark( b ) {
		var i;

		b.tic();
		for ( i = 0; i < b.iterations; i++ ) {
			dlabrd( M, N, NB, A, sA1, sA2, 0, D, 1, 0, E, 1, 0, TAUQ, 1, 0, TAUP, 1, 0, X, sX1, sX2, 0, Y, sY1, sY2, 0 ); // eslint-disable-line max-len
			if ( isnan( A[ i%M ] ) ) {
				b.fail( 'should not return NaN' );
			}
		}
		b.toc();
		if ( isnan( A[ i%M ] ) ) {
			b.fail( 'should not return NaN' );
		}
		b.pass( 'benchmark finished' );
		b.end();
	}
}


// MAIN //

/**
* Main execution sequence.
*
* @private
*/
function main() {
	var minVal;
	var maxVal;
	var ord;
	var NB;
	var N;
	var f;
	var i;
	var j;

	minVal = 1; // 10^minVal
	maxVal = 6; // 10^maxVal

	for ( j = 0; j < LAYOUTS.length; j++ ) {
		ord = LAYOUTS[ j ];
		for ( i = minVal; i <= maxVal; i++ ) {
			N = floor( pow( pow( 10, i ), 1.0/3.0 ) );
			NB = N;
			f = createBenchmark( ord, N, N, NB );
			bench( format( '%s:ndarray:order=%s,size=%d', pkg, ord, N*N ), f );
		}
	}
}

main();
